import * as React from "react";

/**
 * The scroll region an app's content actually lives in.
 *
 * `AppShell scroll="shell"` moves the scroller off the window and onto
 * `AppMain`, so `window.scrollTo(0, 0)` -- the reflex for "go back to the top"
 * -- silently does nothing there: the window has no overflow left to scroll.
 * It fails quietly, which is what makes it expensive. A multi-page shell app
 * looks correct until you follow a link from halfway down a long page and land
 * halfway down the next one.
 *
 * `AppMain` publishes the right scroller here, so a page nested anywhere inside
 * it can ask for the top without knowing which scroll model its Layout chose.
 * Outside an `AppMain` the region falls back to the window, which is what a
 * document-scroll page wanted anyway.
 */
export interface ScrollRegion {
  /** Scroll the app's content region back to the top. */
  scrollToTop: () => void;
  /**
   * The scrolling element, when the region has one. `null` for a
   * document-scroll app, where the page itself scrolls. Lets a hook below an
   * `AppMain` read and write the offset without the Layout's ref.
   */
  getElement?: () => HTMLElement | null;
}

const WINDOW_REGION: ScrollRegion = {
  scrollToTop: () => window.scrollTo(0, 0),
  getElement: () => null,
};

const ScrollRegionContext = React.createContext<ScrollRegion>(WINDOW_REGION);

/**
 * Publishes a scroll region to the subtree below it. `AppMain` does this for
 * you with whichever scroller its `scroll` prop selected; reach for it directly
 * only when an app owns a scroller the design system does not.
 */
export const ScrollRegionProvider = ScrollRegionContext.Provider;

/**
 * The scroll region this subtree lives in. For the common "put me back at the
 * top when X changes" case use `useScrollReset`; this is the imperative escape
 * hatch (a back-to-top button, scrolling after a submit).
 */
export function useScrollRegion(): ScrollRegion {
  return React.useContext(ScrollRegionContext);
}

/**
 * Scrolls the region back to the top whenever `key` changes, skipping the
 * initial mount.
 *
 * The counterpart to `useRouteFocus`, and deliberately a separate hook: that
 * one moves focus with `preventScroll` so navigation does not jump, which
 * leaves the scroll position exactly where the last page left it. A Layout
 * wants both, on the same key and the same ref:
 *
 * ```tsx
 * useRouteFocus(location.pathname, mainRef);
 * useScrollReset(location.pathname, mainRef);
 * ```
 *
 * **Why the ref is a parameter and not just the context**: the Layout that
 * renders `AppMain` sits *above* the provider `AppMain` installs, so it cannot
 * read it -- a component never consumes a context it renders. The Layout is
 * also exactly where route resets belong, so the hook takes the ref it already
 * has (and already passes to `AppMain`), matching `useRouteFocus`'s shape.
 *
 * Omit the ref *below* an `AppMain` and the region comes from context instead,
 * which is what a page wants: it has no ref, and no business knowing which
 * scroll model the Layout chose. Pages pass their own key when they swap
 * content in place -- a lesson moving from reading to quiz changes no URL, but
 * it is still a new screenful and belongs at the top of one.
 *
 * The scroll is instant, never smooth: an animated scroll on arrival races the
 * render of the page just asked for, and reduced-motion users would have to sit
 * out an animation carrying no information.
 */
export function useScrollReset(
  key: unknown,
  ref?: React.RefObject<HTMLElement | null>,
): void {
  const region = useScrollRegion();
  const isFirstRender = React.useRef(true);

  React.useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    if (ref) {
      const el = ref.current;
      // Overflow of its own is what makes an element the scroller. A
      // document-scroll Layout hands us the same `<main>` ref, but there the
      // page scrolls and the element does not -- so ask, rather than making
      // the caller restate a scroll model it already declared on `AppMain`.
      if (el && el.scrollHeight > el.clientHeight) el.scrollTop = 0;
      else window.scrollTo(0, 0);
      return;
    }
    region.scrollToTop();
  }, [key, ref, region]);
}


/** Where each view was left. Session-scoped; a reload starts clean. */
const scrollMemory = new Map<string, number>();

/** How long to keep re-applying a restored offset while content lands. */
const SETTLE_MS = 400;

/**
 * Remembers where a view was scrolled to and returns you there.
 *
 * `useScrollReset` sends every arrival to the top, which is right the first
 * time you open something and wrong every time you come back: leaving a
 * half-read page for another tab and returning put you at the top of it.
 * This remembers per `key` -- a route, a tab, whatever the caller calls a
 * view -- and falls back to the top for a key it has not seen.
 *
 * Three things make it work where the obvious version does not:
 *
 * - **The offset is recorded as you scroll**, not when you leave. React runs an
 *   effect cleanup *after* the DOM has swapped, so reading the position then
 *   returns the incoming view's, and the outgoing view is saved as garbage.
 * - **The scroller is resolved on every read**, because at arrival the content
 *   is often still loading and an element that will overflow does not yet --
 *   resolving once would address the window instead, which scrolls nothing in a
 *   shell layout.
 * - **A restored offset is re-applied for a short window**, since content that
 *   arrives asynchronously leaves the scroller too short and the browser clamps
 *   a write that overshoots. The window ends early the moment the user scrolls,
 *   so it can never fight them for it.
 */
export function useScrollMemory(
  key: string,
  ref?: React.RefObject<HTMLElement | null>,
): void {
  const region = useScrollRegion();
  const keyRef = React.useRef(key);
  // Set while this hook is writing, so its own writes are not mistaken for the
  // user taking over.
  const writing = React.useRef(false);

  // Record continuously. Coalesced to one write per frame: scroll fires far
  // more often than that and the value only has to be right when we leave.
  React.useEffect(() => {
    const el = ref?.current ?? region.getElement?.() ?? null;
    if (!el) return;
    let frame = 0;
    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        scrollMemory.set(keyRef.current, el.scrollTop);
      });
    };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      el.removeEventListener("scroll", onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [ref, region]);

  React.useLayoutEffect(() => {
    keyRef.current = key;
    const remembered = scrollMemory.get(key);

    // An element only counts as the scroller once it actually overflows; a
    // document-scroll Layout hands over the same ref and falls through here.
    const scroller = () => {
      const el = ref?.current ?? region.getElement?.() ?? null;
      return el && el.scrollHeight > el.clientHeight ? el : null;
    };
    const write = (y: number) => {
      writing.current = true;
      const el = scroller();
      if (el) el.scrollTop = y;
      else if (ref) window.scrollTo(0, y);
      else if (y === 0) region.scrollToTop();
      writing.current = false;
    };

    if (!remembered) {
      write(0);
      return;
    }

    write(remembered);
    // Keep re-applying while the view fills in, and stop as soon as it fits or
    // the user takes over.
    let raf = 0;
    let cancelled = false;
    const deadline = performance.now() + SETTLE_MS;
    const giveUp = () => {
      cancelled = true;
    };
    const el = ref?.current ?? region.getElement?.() ?? null;
    el?.addEventListener("wheel", giveUp, { passive: true, once: true });
    el?.addEventListener("touchstart", giveUp, { passive: true, once: true });
    const step = () => {
      const target = scroller();
      if (cancelled || !target || performance.now() > deadline) return;
      if (target.scrollTop !== remembered) write(remembered);
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => {
      cancelled = true;
      if (raf) cancelAnimationFrame(raf);
      el?.removeEventListener("wheel", giveUp);
      el?.removeEventListener("touchstart", giveUp);
    };
  }, [key, ref, region]);
}
